def trend_report(values_by_group):
    """Group records by region and smooth each group's numeric series before averaging."""
    smoothed_groups = {}
    for region, values in values_by_group.items():
        if not values:
            smoothed_groups[region] = []
            continue
        # Simple smoothing: average of current and previous valid values
        smoothed = []
        for i, val in enumerate(values):
            if i == 0:
                smoothed.append(val)
            else:
                smoothed.append((val + smoothed[-1]) / 2)
        smoothed_groups[region] = smoothed
    return smoothed_groups

